import { describe, expect, it } from 'vitest';
import { chooseAction } from '../ai';
import { overwhelming } from '../ai/bid';
import { sampleDeal } from '../ai/knowledge';
import { random } from '../ai/shared';
import { applyAction, legalActionsFor, newGame, viewFor } from '../game';
import { buildReplay, expandReplay, rebuildFromLog, replayLog } from '../replay';
import { buildScenario, checkState } from '../scenario';
import { resolveRules } from '../scoring';
import type { Action, GameState, SeatIndex } from '../types';
// Frozen synthetic games generated by engine dd5756c, before the solo rule.
import archived from './fixtures/legacy-shoot.json';
import continuation from './fixtures/legacy-shoot-continuation.json';

const seats = [0, 1, 2, 3] as const;
const spades = [...'ATKQJ9'].flatMap(rank => [`${rank}S0`, `${rank}S1`]);
function decision(bidder: SeatIndex = 0, score = 0, made = true) {
  return buildScenario({ dealer: ((bidder + 3) % 4) as SeatIndex, bidder, trump: 'S',
    handNumber: 2, score: bidder % 2 ? { blue: score } : { red: score },
    rules: { scoring: 'modern', shoot: 'on', passCount: 0 },
    hands: { [bidder]: made ? spades : ['9H', '9H', 'JH', 'JH', '9D', '9D', 'JD', 'JD', '9C', '9C', 'JC', 'JC'] },
    to: 'deciding_shoot' }).state;
}
function playOut(state: GameState, sampled = false) {
  while (state.phase === 'playing') {
    const seat = state.turn!;
    const view = viewFor(state, seat);
    if (sampled) {
      const deal = sampleDeal(view, random(`${state.rev}`));
      expect(deal).not.toBeNull();
      expect(deal!.map(h => h.length)).toEqual(view.handCounts);
    }
    state = applyAction(state, chooseAction(view, { seed: `${state.rev}`, budgetMs: sampled ? 4 : 0 }));
    expect(checkState(state)).toEqual([]);
  }
  return state;
}

describe('solo shooting', () => {
  it('rejects auction shoots, even for an overwhelming hand, with shooting on', () => {
    const state = newGame('auction', { shoot: 'on' });
    for (const seat of seats) {
      expect(legalActionsFor(state, seat).canShoot).toBe(false);
      expect(() => applyAction(state, { type: 'shoot', seat })).toThrow();
    }
    const stacked = buildScenario({ dealer: 3, rules: { shoot: 'on' }, hands: { 0: spades } }).state;
    expect(chooseAction(viewFor(stacked, 0)).type).not.toBe('shoot');
    expect(legalActionsFor(newGame('off'), 1).canShoot).toBe(false);
  });

  it.each(seats)('plays three-card tricks clockwise around the sitting-out partner of seat %i', bidder => {
    const before = decision(bidder);
    let state = applyAction(before, { type: 'shoot', seat: bidder });
    const sittingOut = ((bidder + 2) % 4) as SeatIndex;
    expect(state).toMatchObject({ phase: 'playing', turn: bidder, sittingOut });
    expect(state.bids).toEqual(before.bids);
    expect(state.bids.some(b => b.shoot)).toBe(false);
    expect(state.players.every(p => p.meld.length === 0 && p.meldPoints === 0)).toBe(true);
    for (const seat of seats) {
      expect(() => applyAction(state, { type: 'declare_meld', seat, cards: [] })).toThrow();
      expect(() => applyAction(state, { type: 'confirm_meld', seat })).toThrow();
    }
    const order = [bidder, (bidder + 1) % 4, (bidder + 3) % 4];
    for (const seat of order) {
      expect(state.turn).toBe(seat);
      state = applyAction(state, { type: 'play_card', seat: state.turn!, card: legalActionsFor(state, state.turn!).playableCards[0] });
    }
    expect(viewFor(state, bidder).recap.tricks[0].plays.map(p => p.seat)).toEqual(order);
    expect(state.turn).toBe(bidder);
    expect(state.players[sittingOut].hand).toEqual(before.players[sittingOut].hand);
    expect(legalActionsFor(state, sittingOut).playableCards).toEqual([]);
    expect(checkState(state)).toEqual([]);
  });

  it('hides the set-aside hand from every view, including its owner and pass histories, until hand end', () => {
    let state = buildScenario({ bidder: 0, trump: 'S', rules: { shoot: 'on' }, to: 'deciding_shoot' }).state;
    state = applyAction(state, { type: 'shoot', seat: 0 });
    const hidden = state.players[2].hand;
    for (const seat of seats) {
      const view = viewFor(state, seat);
      const json = JSON.stringify(view);
      for (const card of hidden) expect(json).not.toContain(`"${card}"`);
      expect(view.handCounts[2]).toBe(12);
      expect(view.revealed).toBeNull();
    }
    expect(viewFor(state, 2).hand).toEqual([]);
    const finished = playOut(state);
    expect(viewFor(finished, 2).revealed?.atPlay[2]).toEqual(hidden);
  });

  it('keeps follow, head, trump and overtrump requirements in three-player tricks', () => {
    const state = applyAction(decision(), { type: 'shoot', seat: 0 });
    state.turn = 3;
    state.currentTrick = { leader: 0, plays: [{ seat: 0, card: '9H0' }, { seat: 1, card: 'JH0' }], winner: null };
    state.players[3].hand = ['AH0', '9H1', 'AS0'];
    expect(legalActionsFor(state, 3).playConstraint?.reason).toBe('must_head');
    expect(legalActionsFor(state, 3).playableCards).toEqual(['AH0']);
    state.currentTrick.plays[1].card = 'AS1';
    expect(legalActionsFor(state, 3).playableCards).toEqual(['AH0', '9H1']);
    state.players[3].hand = ['KS0', '9C0'];
    state.currentTrick.plays[1].card = 'JH0';
    expect(legalActionsFor(state, 3).playConstraint?.reason).toBe('must_trump');
    state.currentTrick.plays[1].card = 'QS0';
    expect(legalActionsFor(state, 3).playConstraint?.reason).toBe('must_overtrump');
    expect(legalActionsFor(state, 3).playableCards).toEqual(['KS0']);
  });

  it.each([0, 19, -30])('adds exactly the target for a made shoot starting at %i', score => {
    const state = playOut(applyAction(decision(0, score), { type: 'shoot', seat: 0 }), true);
    expect(state.score.red).toBe(score + 150);
    expect(state.winner).toBe(score < 0 ? null : 'red');
    expect(state.phase).toBe(score < 0 ? 'hand_over' : 'game_over');
    expect(state.players[0].hand).toEqual([]);
    expect(state.players[2].hand).toHaveLength(12);
    expect(viewFor(state, 0).playedCards).toHaveLength(36);
    const record = state.history.at(-1)!;
    expect(record).toMatchObject({ shotMade: true, meld: { red: 0, blue: 0 }, tricks: { red: 0, blue: 0 }, delta: { red: 150, blue: 0 } });
    for (const team of ['red', 'blue'] as const) expect(record.breakdown[team]).toMatchObject({ meldDeclared: 0, meldSaved: 0, counters: 0, lastTrick: 0, setPenalty: 0 });
    if (score < 0) {
      const next = applyAction(state, { type: 'next_hand', seat: 0 });
      expect(next.sittingOut).toBeNull();
      expect(next.players.every(p => p.hand.length === 12)).toBe(true);
    }
  });

  it.each(seats)('ends the game on the first trick lost by declarer %i, regardless of scores', bidder => {
    let state = decision(bidder, 999, false);
    state = applyAction(state, { type: 'shoot', seat: bidder });
    state = playOut(state, true);
    expect(state).toMatchObject({ phase: 'game_over', winner: bidder % 2 ? 'red' : 'blue' });
    expect(viewFor(state, bidder).recap.tricks).toHaveLength(1);
    expect(state.players.filter(p => p.seat !== state.sittingOut).every(p => p.hand.length === 11)).toBe(true);
    expect(state.history.at(-1)).toMatchObject({ shotMade: false, delta: { red: 0, blue: 0 }, meld: { red: 0, blue: 0 }, tricks: { red: 0, blue: 0 } });
  });

  it('declines a solo hand with a side-suit loser or inadequate trump control, regardless of partner signals', () => {
    const safe = decision();
    expect(overwhelming(viewFor(safe, 0))).toBe(true);
    const weak = decision(0, 0, false);
    expect(chooseAction(viewFor(weak, 0)).type).toBe('decline_shoot');
    const view = viewFor(safe, 0);
    view.hand[11] = 'KH0';
    expect(overwhelming(view)).toBe(false);
    view.hand = ['AS0', 'AS1', 'KS0', 'KS1', 'QS0', 'QS1', 'JS0', 'JS1', '9S0', 'AH0', 'AD0', 'AC0'];
    expect(overwhelming(view)).toBe(false);
    view.bids = [{ seat: 2, amount: 140 }];
    expect(overwhelming(view)).toBe(false);
  });

  it.each(['game', 'points'])('normalizes stored %s rules to on and discards the old stake', shoot => {
    const stored = { scoring: 'modern', shoot, shootPoints: 100 };
    const rules = resolveRules(stored);
    expect(rules.shoot).toBe('on');
    expect(rules).not.toHaveProperty('shootPoints');
    expect(newGame('mapped', stored as unknown as GameState['rules']).rules).toEqual(rules);
    expect(viewFor({ ...newGame('stored'), rules: stored as unknown as GameState['rules'] }, 0).rules.shoot).toBe('on');
  });
});

describe('archived four-player shoots', () => {
  it('preserves an old points stake when continuing an ordinary second hand', () => {
    // dd5756c played the auction shoot and dealt hand two before this deployment.
    const before = continuation.final as unknown as GameState;
    expect(before).toMatchObject({ phase: 'bidding', handNumber: 2 });
    expect(before.highBid).toBeNull();
    expect(before.legacyShootRules).toBeUndefined();
    const action: Action = { type: 'bid', seat: before.turn!, amount: before.rules.minBid };
    const after = applyAction(before, action);
    expect(after.rules).not.toHaveProperty('shootPoints');
    expect(after.legacyShootRules).toEqual({ mode: 'points', points: 100 });
    const rebuilt = rebuildFromLog(after, [...continuation.actions as Action[], action]);
    expect(rebuilt).not.toBeNull();
    expect(rebuilt!.states.at(-1)!.score).toEqual(after.score);
  });

  it.each(archived)('replays a stored $mode shoot declared $timing', fixture => {
    const final = fixture.final as unknown as GameState;
    const actions = fixture.actions as Action[];
    const rebuilt = rebuildFromLog(final, actions);
    expect(rebuilt).not.toBeNull();
    expect(rebuilt!.states.at(-1)!.players).toEqual(final.players);
    expect(rebuilt!.states.at(-1)!.score).toEqual(final.score);
    const replay = buildReplay(rebuilt!.states, rebuilt!.actions)!;
    expect(expandReplay(JSON.parse(JSON.stringify(replay))).at(-1)!.score).toEqual(final.score);
    expect(replayLog(rebuilt!.start, rebuilt!.actions).states.at(-1)!.players).toEqual(final.players);
    // An in-progress stored hand has the old raw rules but no new compatibility metadata.
    const beforeLast = { ...rebuilt!.states.at(-2)!, rules: final.rules };
    delete beforeLast.legacyShootRules;
    expect(applyAction(beforeLast, actions.at(-1)!).score).toEqual(final.score);
  });
});
